mapper.select:
SELECT m.movement_id AS id, m.material_id AS product_id, l.location_code AS store_id, CASE m.movement_type WHEN 'IN' THEN '入库' WHEN 'OUT' THEN '出库' ELSE '调整' END AS type, m.change_qty AS change_amount, m.balance_after AS after_stock, m.source_ref AS remark, m.create_time FROM inventory_movement m JOIN locations l ON l.location_id = m.location_id AND l.deleted = 0 WHERE l.location_type = 'STORE'
AND l.location_code = #{storeId}
AND m.material_id = #{productId}
AND CASE m.movement_type WHEN 'IN' THEN '入库' WHEN 'OUT' THEN '出库' ELSE '调整' END = #{type}
ORDER BY m.create_time DESC
